using Suishouyi.Core;
using Microsoft.Win32;
using System.Diagnostics;
using System.Reflection;
namespace Suishouyi.Installer;
internal sealed class InstallerForm:Form {
 const string RegistryPath=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\Suishouyi";
 readonly string destination=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Suishouyi");readonly Label status=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};readonly Button action=new(){Size=new(140,38)};bool working;
 public InstallerForm(bool uninstall){Text=uninstall?"卸载随手译":"安装随手译";Size=new(510,260);StartPosition=FormStartPosition.CenterScreen;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;Font=new("Microsoft YaHei UI",10);Padding=new(24);BackColor=Color.FromArgb(245,247,252);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};layout.RowStyles.Add(new(SizeType.Percent,100));layout.RowStyles.Add(new(SizeType.Absolute,45));Controls.Add(layout);status.Text=uninstall?"卸载随手译。个人设置、本人账号和共享 CodeBuddy 会保留。":"安装随手译 1.2.0 到当前用户。运行时和中英文 OCR 随包，首次使用自动准备 CodeBuddy。\n\n此包为未签名候选版，Windows 实机验证尚未完成。";layout.Controls.Add(status);action.Text=uninstall?"卸载随手译":"安装并启动";action.BackColor=Color.FromArgb(99,85,226);action.ForeColor=Color.White;action.FlatStyle=FlatStyle.Flat;layout.Controls.Add(action);action.Click+=async(_,_)=>{working=true;action.Enabled=false;try{await StopRunningAsync();if(uninstall){working=false;Remove();Close();}else{status.Text="正在安装…";await Task.Run(Install);status.Text="安装完成。正在启动首次使用引导…";working=false;Close();}}catch(Exception ex){status.Text="未完成："+ex.Message;action.Enabled=true;}finally{working=false;}};FormClosing+=(_,e)=>{if(working)e.Cancel=true;};}
 async Task StopRunningAsync(){try{using var signal=EventWaitHandle.OpenExisting("Local\\Suishouyi.Shutdown."+Environment.UserName);signal.Set();}catch(WaitHandleCannotBeOpenedException){}foreach(var process in Process.GetProcessesByName("Suishouyi")){using(process){if(process.MainModule?.FileName is not string file||!string.Equals(Path.GetFullPath(file),Path.Combine(destination,"Suishouyi.exe"),StringComparison.OrdinalIgnoreCase))continue;using var timeout=new CancellationTokenSource(6000);try{await process.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException){throw new IOException("请从托盘退出旧版随手译后重试。旧程序保留。");}}}}
 void Install(){using var archive=Assembly.GetExecutingAssembly().GetManifestResourceStream("Suishouyi.Payload")??throw new InvalidDataException("安装包缺少程序文件。");PayloadInstaller.Install(archive,destination,()=>{File.Copy(Environment.ProcessPath!,Path.Combine(destination,"Uninstall.exe"),true);CreateShortcut();using var key=Registry.CurrentUser.CreateSubKey(RegistryPath);key.SetValue("DisplayName","随手译");key.SetValue("DisplayVersion","1.2.0");key.SetValue("Publisher","随手译");key.SetValue("InstallLocation",destination);key.SetValue("UninstallString",$"\"{Path.Combine(destination,"Uninstall.exe")}\" --uninstall");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);Process.Start(new ProcessStartInfo(Path.Combine(destination,"Suishouyi.exe")){UseShellExecute=true});});}
 string ShortcutPath=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"随手译.lnk");
 void CreateShortcut(){var shellType=Type.GetTypeFromProgID("WScript.Shell")??throw new IOException("无法创建启动入口。");dynamic shell=Activator.CreateInstance(shellType)!;dynamic shortcut=shell.CreateShortcut(ShortcutPath);shortcut.TargetPath=Path.Combine(destination,"Suishouyi.exe");shortcut.WorkingDirectory=destination;shortcut.Description="随手译 · 翻译与解释选中文字";shortcut.Save();System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}
 void Remove(){if(File.Exists(ShortcutPath))File.Delete(ShortcutPath);Registry.CurrentUser.DeleteSubKeyTree(RegistryPath,false);var script=Path.Combine(Path.GetTempPath(),"suishouyi-uninstall-"+Guid.NewGuid()+".ps1");var literal=destination.Replace("'","''");File.WriteAllText(script,$"Wait-Process -Id {Environment.ProcessId} -ErrorAction SilentlyContinue\nRemove-Item -LiteralPath '{literal}' -Recurse -Force\nif(Test-Path -LiteralPath '{literal}.previous'){{Remove-Item -LiteralPath '{literal}.previous' -Recurse -Force}}\nRemove-Item -LiteralPath $MyInvocation.MyCommand.Path -Force\n",new System.Text.UTF8Encoding(true));var start=new ProcessStartInfo("powershell.exe"){CreateNoWindow=true,UseShellExecute=false};foreach(var arg in new[]{"-NoProfile","-ExecutionPolicy","Bypass","-File",script})start.ArgumentList.Add(arg);Process.Start(start);}
}
